#include <iostream>

int main() {
    int a = 7, b = 2;
    std::cout << a / b << '\n';                      // 3  - integer division truncates
    std::cout << -a / b << '\n';                     // -3 - truncation is toward zero
    double d = a / b;                                // division already happened in int
    std::cout << d << '\n';                          // 3
    std::cout << static_cast<double>(a) / b << '\n'; // 3.5 - cast BEFORE dividing
    return 0;
}

